            html_string.insert(insert_position + final_element_text.length(), "</li>\n");
        }

        pos += IsNumber(first_char(final_element_text), '#') // check for ordered-lists (# followed by digits)
            ? static_cast<size_t>((insert_position - html_string.begin()) + final_element_text.find("#") + 1) // Add marker text length + # index
             : static_cast<size_t>(html_string.find_last_not_of("\n")) + 3; // Add new line character

        html_string.insert(pos, is_bullet_list? "<ul>" : "<ol>");
        pos += is_bullet_list? 4 : 3; // Add list element tag length
    }

    // Add code blocks
    while ((pos = md_text.find_first_of("`", pos))!= std::string::npos) {

        auto code_start = std::next(md_text.begin() + pos, 1); // start at the'after backticks
        auto code_end = std::next(code_start, md_text.find_first_not_of("`\n", code_start));
        std::string code_block = std::string(code_start, code_end);

        // Replace backticks with `<pre>`/`</pre>` tags
        std::string pre_tags("<pre><code>");
        html_string.insert(pos, pre_tags);
        pos += pre_tags.length();

        // Escape HTML characters
        auto escaped_text = escape_html(code_block);
        html_string.append(escaped_text);
        pos += escaped_text.length();

        std::string post_tags("</code></pre>");
        html_string.insert(pos, post_tags);
        pos += post_tags.length();
    }

    // Convert remaining plain text
    auto plain_text_begin = std::remove_if(md_text.begin(), md_text.end(),
                           [](unsigned char c){return!std::isprint(c);});
    auto plain_text_end = std::find(md_text.rbegin(), md_text.rend(), '\n').base();

    html_string.append(plain_text_begin, plain_text_end);

    return html_string;
}
```

This implementation covers some basic elements like emphasis markers (`**` and `_`), bullet-pointed and numbered lists, fenced code blocks (``` `), and converting plain text without formatting to actual HTML tags. Feel free to modify, extend, or adjust as per your specific needs!

